import numpy as np
import itertools
import json

def task_func(data_list, json_file_name="mean_values.json"):
    means = {}
    for i, values in enumerate(itertools.zip_longest(*data_list, fillvalue=None)):
        numeric_values = [value for value in values if isinstance(value, (int, float))]
        means[f"Position {i}"] = float(np.mean(numeric_values))

    if json_file_name:
        with open(json_file_name, "w", encoding="utf-8") as json_file:
            json.dump(means, json_file)

    return means

