import threading

def task_func(delay_time: float = 1.0, num_threads: int = 5):
    messages = [None for _ in range(num_threads)]

    def delay_in_thread(index):
        time.sleep(delay_time)
        messages[index] = f'Delay in thread {index} completed'

    threads = [
        threading.Thread(target=delay_in_thread, args=(index,))
        for index in range(num_threads)
    ]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return messages

